    type: "image" | "video";
    content: ImageMessageContent | VideoMessageContent;
  } | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadMedia = async () => {
      try {
        setLoading(true);
        const info = getMediaInfo(item);
        setInfo(info);
