          const thumbSource = videoContent.info?.thumbnailSource;
          if (!thumbSource) return;
          const mxcUrl = thumbSource.url();
          if (!mxcUrl) return;

          if (await isCached(mxcUrl)) {
            setUri(getCachedImagePathByURL(mxcUrl));
            return;
          }

          const url = await fetchMedia({
            serverUrl:
              MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
            mediaSource: thumbSource,
            mimeType: "image/jpeg",
          });
          if (!url) return;
          await cacheImageWithKey(mxcUrl, url);
          setUri(getCachedImagePathByURL(mxcUrl));
        }
      } catch (e) {
        console.error("Failed to load media thumbnail:", e);
      } finally {
        setLoading(false);
      }
    };

    loadMedia();
  }, [item]);

  return (
    <Button.Wrapper onPress={() => onPress(uri, info?.type, info?.content)}>
      <Block
        width={ITEM_SIZE}
        height={ITEM_SIZE}
        background={Colors.white20}
        border={{ borderRadius: 4 }}
        overflow="hidden"
        align="center"
        justify="center"
      >
        {uri ? (
          <Image
            source={{ uri }}
            width={ITEM_SIZE}
            height={ITEM_SIZE}
            resizeMode="cover"
          />
        ) : (
          loading && <Loading isFullScreen={false} />
        )}

        {info?.type === "video" && !loading && (
          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
            align="center"
            justify="center"
            pointerEvents="none"
          >
            <Block
              background={Colors.primary}
              width={24}
              height={24}
              align="center"
              justify="center"
              border={{ borderRadius: 999 }}
            >
              <Image
                tintColor={Colors.white}
                source={require("assets/icons/play.png")}
                style={styles.playButton}
              />
            </Block>
          </Block>
        )}
      </Block>
    </Button.Wrapper>
  );
};

const styles = StyleSheet.create({
  playButton: {
    width: 16,
    height: 16,
  },
});

