import ReactNativeBlobUtil from "react-native-blob-util";

const CacheDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir}/videos`;
const PrefixlessCacheDir = CacheDir.replace("file://", "");
const CurrentBatch = new Map<string, Promise<void>>();
let CacheDirReady = false;

const MIME_TO_EXT: Record<string, string> = {
  "video/mp4": ".mp4",
  "video/quicktime": ".mov",
  "video/webm": ".webm",
  "video/x-matroska": ".mkv",
  "video/ogg": ".ogv",
  "video/3gpp": ".3gp",
  "video/3gpp2": ".3g2",
};

export function extFromMimeType(mimeType: string): string {
  return MIME_TO_EXT[mimeType] ?? ".mp4";
}

function getFilenameByURL(url: string) {
  let hash = 0;
  for (let i = 0; i < url.length; i++) {
    hash = (hash << 5) - hash + url.charCodeAt(i);
    hash |= 0;
  }
  return (hash >>> 0).toString(36);
}

/** Returns storage path associated with provided URL, including the file:// prefix */
export function getCachedVideoPathByURL(url: string, ext: string) {
  const fileName = getFilenameByURL(url);
  return `file://${PrefixlessCacheDir}/${fileName}${ext}`;
}

function getStoragePathByUrl(url: string, ext: string) {
  const fileName = getFilenameByURL(url);
  return `${PrefixlessCacheDir}/${fileName}${ext}`;
}

async function downloadToPath(url: string, localFilePath: string) {
  if (url.startsWith("file://")) {
    await ReactNativeBlobUtil.fs.cp(url.replace("file://", ""), localFilePath);
    return;
  }

  const responseRaw = await ReactNativeBlobUtil.config({
    path: localFilePath,
  }).fetch("GET", url);

  const response = responseRaw.info();
  const status = response.status;

  if (status < 200 || status >= 300) {
    await ReactNativeBlobUtil.fs.unlink(localFilePath);
    throw new Error(`Unable to cache ${url}, http ${status}`);
  }
}

async function ensureCached(
  cacheKey: string,
  downloadUrl: string,
  ext: string,
): Promise<void> {
  const batchKey = `${cacheKey}${ext}`;
  if (CurrentBatch.has(batchKey)) {
    return CurrentBatch.get(batchKey);
  }

  const localFilePath = getStoragePathByUrl(cacheKey, ext);
  const cachingPromise = (async () => {
    try {
      if (!CacheDirReady) {
        const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
        if (!dirExists) await ReactNativeBlobUtil.fs.mkdir(CacheDir);
        CacheDirReady = true;
      }

      const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
      if (!fileExists) {
        await downloadToPath(downloadUrl, localFilePath);
      } else {
        const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
        if (!stat || stat.size === 0) {
          await ReactNativeBlobUtil.fs.unlink(localFilePath);
          await downloadToPath(downloadUrl, localFilePath);
        }
      }
    } catch (error) {
      console.warn(
        `Failed to cache video ${downloadUrl} to ${localFilePath}:`,
        error,
      );
    } finally {
      CurrentBatch.delete(batchKey);
    }
  })();

  CurrentBatch.set(batchKey, cachingPromise);
  return cachingPromise;
}

/** Returns true if the video for the given URL is already cached on disk. */
export async function isVideoCached(url: string, ext: string): Promise<boolean> {
  const localFilePath = getStoragePathByUrl(url, ext);
  try {
    const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
    if (!fileExists) return false;
    const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
    return !!stat && stat.size > 0;
  } catch {
    return false;
  }
}

/**
 * Caches a video using `cacheKey` as the cache identifier (e.g. MXC URL)
 * but copies/downloads from `downloadUrl` (e.g. local temp file path from fetchMedia).
 */
export async function cacheVideoWithKey(
  cacheKey: string,
  downloadUrl: string,
  ext: string,
): Promise<void> {
  return ensureCached(cacheKey, downloadUrl, ext);
}

/** Removes all cached videos from disk. Call on logout. */
export async function clearVideoCache(): Promise<void> {
  try {
    const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
    if (dirExists) {
      await ReactNativeBlobUtil.fs.unlink(CacheDir);
    }
  } catch (error) {
    console.warn("Failed to clear video cache:", error);
  } finally {
    CacheDirReady = false;
    CurrentBatch.clear();
  }
}

