export async function clearMediaEncryptionKey(): Promise<void> {
  cachedKey = null;
  keyPromise = null;
  try {
    await Keychain.resetGenericPassword({ service: KEYCHAIN_SERVICE });
  } catch (e) {
    console.warn("Failed to clear media encryption key:", e);
  }
}

