2	import * as Keychain from "react-native-keychain";
3	import QuickCrypto, { Buffer } from "react-native-quick-crypto";
4	
5	// Service identifier under which the AES-256 data key is stored in the
6	// iOS Keychain / Android Keystore. The key is hardware-backed where available
7	// and lives outside the app sandbox. Shared by the encrypted image and
8	// video caches.
9	const KEYCHAIN_SERVICE = "com.prototyp.cloak.media-cache";
10	// Earlier image-only version of this module used a different service name.
11	// We migrate existing entries on first access so already-encrypted ciphertext
12	// stays decryptable after the rename.
13	const LEGACY_KEYCHAIN_SERVICE = "com.prototyp.cloak.image-cache";
14	
15	const KEY_LENGTH = 32; // AES-256
16	const IV_LENGTH = 12; // GCM nonce
17	const TAG_LENGTH = 16; // GCM auth tag
18	const FORMAT_VERSION = 1;
19	
20	let cachedKey: Buffer | null = null;
21	let keyPromise: Promise<Buffer> | null = null;
22	
23	async function loadOrCreateKey(): Promise<Buffer> {
24	  const stored = await Keychain.getGenericPassword({
25	    service: KEYCHAIN_SERVICE,
26	  });
27	  if (stored && "password" in stored && stored.password) {
28	    return Buffer.from(stored.password, "base64");
29	  }
30	
31	  const legacy = await Keychain.getGenericPassword({
32	    service: LEGACY_KEYCHAIN_SERVICE,
33	  });
34	  if (legacy && "password" in legacy && legacy.password) {
35	    await Keychain.setGenericPassword("media-cache", legacy.password, {
36	      service: KEYCHAIN_SERVICE,
37	      accessible: Keychain.ACCESSIBLE.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
38	    });
39	    try {
40	      await Keychain.resetGenericPassword({ service: LEGACY_KEYCHAIN_SERVICE });
41	    } catch {}
42	    return Buffer.from(legacy.password, "base64");
43	  }
44	
45	  const fresh = QuickCrypto.randomBytes(KEY_LENGTH);
46	  await Keychain.setGenericPassword("media-cache", fresh.toString("base64"), {
47	    service: KEYCHAIN_SERVICE,
48	    accessible: Keychain.ACCESSIBLE.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
49	  });
50	  return fresh;
51	}
52	
53	async function getKey(): Promise<Buffer> {
54	  if (cachedKey) return cachedKey;
55	  if (!keyPromise) {
56	    keyPromise = loadOrCreateKey()
57	      .then((k) => {
58	        cachedKey = k;
59	        return k;
60	      })
61	      .finally(() => {
62	        keyPromise = null;
63	      });
64	  }
65	  return keyPromise;
66	}
67	
68	function stripFilePrefix(path: string): string {
69	  return path.startsWith("file://") ? path.slice("file://".length) : path;
70	}
71	
72	/**
73	 * Reads `plaintextPath`, encrypts with AES-256-GCM, and writes the result to
74	 * `ciphertextPath`. File format: [1B version][12B IV][ciphertext][16B tag].
75	 *
76	 * Whole-file in-memory round trip via base64. Fine for images and typical
77	 * chat videos; videos larger than ~50 MB will put sustained pressure on the
78	 * JS heap.
79	 */
80	export async function encryptFile(
81	  plaintextPath: string,
82	  ciphertextPath: string,
83	): Promise<void> {
84	  const key = await getKey();
85	  const base64 = await ReactNativeBlobUtil.fs.readFile(
86	    stripFilePrefix(plaintextPath),
87	    "base64",
88	  );
89	  const plaintext = Buffer.from(base64, "base64");
90	
91	  const iv = QuickCrypto.randomBytes(IV_LENGTH);
92	  const cipher = QuickCrypto.createCipheriv("aes-256-gcm", key, iv);
93	  const body = Buffer.concat([cipher.update(plaintext), cipher.final()]);
94	  const tag = cipher.getAuthTag();
95	
96	  const out = Buffer.concat([Buffer.from([FORMAT_VERSION]), iv, body, tag]);
97	  await ReactNativeBlobUtil.fs.writeFile(
98	    stripFilePrefix(ciphertextPath),
99	    out.toString("base64"),
100	    "base64",
101	  );
102	}
103	
104	/**
105	 * Reads ciphertext at `ciphertextPath`, decrypts, and writes plaintext to
106	 * `plaintextPath`. Throws if the auth tag doesn't verify.
107	 */
108	export async function decryptFile(
109	  ciphertextPath: string,
110	  plaintextPath: string,
111	): Promise<void> {
112	  const key = await getKey();
113	  const base64 = await ReactNativeBlobUtil.fs.readFile(
114	    stripFilePrefix(ciphertextPath),
115	    "base64",
116	  );
117	  const buf = Buffer.from(base64, "base64");
118	
119	  const version = buf[0];
120	  if (version !== FORMAT_VERSION) {
121	    throw new Error(`Unsupported media cache format: ${version}`);
122	  }
123	  const iv = buf.subarray(1, 1 + IV_LENGTH);
124	  const tag = buf.subarray(buf.length - TAG_LENGTH);
125	  const body = buf.subarray(1 + IV_LENGTH, buf.length - TAG_LENGTH);
126	
127	  const decipher = QuickCrypto.createDecipheriv("aes-256-gcm", key, iv);
128	  decipher.setAuthTag(tag);
129	  const plaintext = Buffer.concat([decipher.update(body), decipher.final()]);
130	
131	  await ReactNativeBlobUtil.fs.writeFile(
132	    stripFilePrefix(plaintextPath),
133	    plaintext.toString("base64"),
134	    "base64",
135	  );
136	}
137	
138	/** Drops the key from memory and the Keychain. Call on logout. */
139	export async function clearMediaEncryptionKey(): Promise<void> {
140	  cachedKey = null;
141	  keyPromise = null;
142	  try {
143	    await Keychain.resetGenericPassword({ service: KEYCHAIN_SERVICE });
144	  } catch (e) {
145	    console.warn("Failed to clear media encryption key:", e);
146	  }
147	  try {
148	    await Keychain.resetGenericPassword({ service: LEGACY_KEYCHAIN_SERVICE });
149	  } catch {}
150	}
